  exact_ids uuid[];
  hnsw_ids uuid[];
  exact_top double precision;
  hnsw_top double precision;
  t0 timestamptz;
  r text := '';
  ef integer;
begin
  set local enable_indexscan = off;
  set local enable_bitmapscan = off;
  t0 := clock_timestamp();
  select array_agg(id order by d), max(1 - d) into exact_ids, exact_top
  from (select id, embedding <=> q as d from public.catalog_items
        where embedding is not null order by embedding <=> q limit 20) x;
  r := r || format('EXATA: melhor similaridade %s, %s ms | ',
        round(exact_top::numeric, 4), round(extract(epoch from clock_timestamp() - t0) * 1000));

  set local enable_indexscan = on;
  set local enable_bitmapscan = on;
  set local enable_seqscan = off;
  foreach ef in array array[40, 100, 500, 1000] loop
    perform set_config('hnsw.ef_search', ef::text, true);
    t0 := clock_timestamp();
    select array_agg(id order by d), max(1 - d) into hnsw_ids, hnsw_top
    from (select id, embedding <=> q as d from public.catalog_items
          where embedding is not null order by embedding <=> q limit 20) x;
    r := r || format('HNSW ef=%s: melhor %s, %s dos 20 iguais, %s ms | ', ef,
          round(hnsw_top::numeric, 4),
          (select count(*) from unnest(hnsw_ids) h where h = any(exact_ids)),
          round(extract(epoch from clock_timestamp() - t0) * 1000));
  end loop;
  raise exception 'RESULTADO: %', r;
end $$;
